package org.firstinspires.ftc.teamcode.subsystems;

import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.hardware.DcMotorSimple;
import com.qualcomm.robotcore.hardware.HardwareMap;

import org.firstinspires.ftc.teamcode.config.DeviceNames;

// Generated by refract-suite ftc-construct. One motor: collects, and feeds BOTH launchers at once
// (NECTAR up the ramp to the front launcher, POLLEN under it to the back launcher).
public class Intake {
    // operating powers, not measurements (DECODE ran 0.8 in, -1 out); feed powers are measured (G-5)
    public static double IN_POWER = 0.8;
    public static double EJECT_POWER = 1.0;
    // set by prerequisites E-3: true if +power pushes balls out
    public static boolean REVERSED = false;

    private final DcMotorEx motor;

    public Intake(HardwareMap hardwareMap) {
        motor = hardwareMap.get(DcMotorEx.class, DeviceNames.INTAKE);
        motor.setDirection(REVERSED ? DcMotorSimple.Direction.REVERSE : DcMotorSimple.Direction.FORWARD);
        motor.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
    }

    public void in() {
        motor.setPower(IN_POWER);
    }

    public void eject(double scale) {
        motor.setPower(-EJECT_POWER * Math.abs(scale));
    }

    // One motor feeds both launchers at once, so the caller passes the slower of the two launchers' feed
    // powers from their shot tables. NaN (no table yet) = no feed.
    public boolean feed(double power) {
        if (Double.isNaN(power)) {
            motor.setPower(0);
            return false;
        }
        motor.setPower(power);
        return true;
    }

    // data collection only (Front / Back Shot Tuner)
    public void run(double power) {
        motor.setPower(power);
    }

    public void stop() {
        motor.setPower(0);
    }
}
